// Imagem 22-Email Enviado.png embutida para renderização 100% garantida (sem bloqueio de URLs externas)
const IMAGEM_BASE64 = "";

export default {
  async scheduled(event, env, ctx) {
    ctx.waitUntil(processEmails(env));
  },

  async fetch(request, env, ctx) {
    const result = await processEmails(env);
    return new Response(JSON.stringify(result, null, 2), {
      headers: { "Content-Type": "application/json" }
    });
  }
};

async function processEmails(env) {
  const backendBaseUrl = (env.BACKEND_URL || "https://ais-dev-s6lh3mjgzwcdeu7aoagn6d-331134434620.europe-west2.run.app").replace(/\/api\/.*$/, "").replace(/\/$/, "");
  const recognizeUrl = `${backendBaseUrl}/api/reconhecer-recibo`;
  const processadoUrl = `${backendBaseUrl}/api/email-processado`;
  const apiSecret = env.CONDOMANAGER_API_SECRET || "condo-secret-key-2025";

  let accessToken;
  try {
    accessToken = await getAccessToken(env);
  } catch (tokenErr) {
    return { success: false, etapa: "OBTER_TOKEN_GMAIL", erro: tokenErr.message };
  }

  const listRes = await fetch(
    "https://gmail.googleapis.com/gmail/v1/users/me/messages?q=is:unread&maxResults=3",
    { headers: { Authorization: `Bearer ${accessToken}` } }
  );

  const listData = await listRes.json();
  if (listData.error) {
    return { success: false, etapa: "LISTAR_MENSAGENS_GMAIL", erroGmail: listData.error };
  }

  const messages = listData.messages || [];
  if (messages.length === 0) {
    return { success: true, totalNaoLidos: 0, mensagem: "Nenhum e-mail não lido." };
  }

  let processed = 0;
  const resultadosProcessados = [];

  for (const msg of messages) {
    try {
      const emailData = await fetch(
        `https://gmail.googleapis.com/gmail/v1/users/me/messages/${msg.id}?format=full`,
        { headers: { Authorization: `Bearer ${accessToken}` } }
      ).then(r => r.json());

      const headers = emailData.payload?.headers || [];
      const rawFrom = getHeader(headers, "From");
      const cleanFrom = extrairEmailLimpo(rawFrom);
      const nomeRemetente = extrairNomeRemetente(rawFrom, cleanFrom);
      const to = getHeader(headers, "To");
      const subject = getHeader(headers, "Subject") || "Sem Assunto";
      const messageId = getHeader(headers, "Message-ID") || msg.id;
      const date = getHeader(headers, "Date") || new Date().toISOString();

      const { bodyText, bodyHtml } = extractBodies(emailData.payload);
      const documentos = await extractAttachments(emailData, accessToken);

      const payload = {
        email: { messageId, from: cleanFrom, to, subject, date: new Date(date).toISOString(), bodyText, bodyHtml },
        predioId: env.PREDIO_ID || "predio-1",
        documentos
      };

      let aiResult = {};
      try {
        const aiResponse = await fetch(recognizeUrl, {
          method: "POST",
          headers: { "Content-Type": "application/json", "x-api-key": apiSecret },
          body: JSON.stringify(payload)
        });
        aiResult = await aiResponse.json();
      } catch (errBackend) {
        aiResult = { aviso: "Erro ao contactar backend IA", detalhe: errBackend.message };
      }

      let resendStatus = "NÃO_APLICÁVEL";
      const eIgnorado = deveIgnorarAutoresponder(rawFrom, cleanFrom, subject, bodyText);

      if (eIgnorado) {
        resendStatus = "IGNORADO_FORNECEDOR_OU_BANCO";
      } else if (env.RESEND_API_KEY && cleanFrom) {
        resendStatus = await enviarRespostaResend(subject, cleanFrom, nomeRemetente, env);
      }

      // GRAVAÇÃO NO SUPABASE DENTRO DO LOOP
      await guardarNoSupabase(
        { messageId, from: cleanFrom, to, subject, date, bodyText },
        aiResult,
        resendStatus,
        documentos,
        env
      );

      try {
        await fetch(processadoUrl, {
          method: "POST",
          headers: { "Content-Type": "application/json", "x-api-key": apiSecret },
          body: JSON.stringify({
            email: { messageId, from: cleanFrom, to, subject, date, bodyText, bodyHtml },
            documentos,
            aiResult,
            resendStatus
          })
        });
      } catch (errSupabase) {
        console.error("Erro ao notificar /api/email-processado:", errSupabase);
      }

      await markAsRead(msg.id, accessToken);
      processed++;
      resultadosProcessados.push({ messageId, subject, from: cleanFrom, resendStatus, aiResult });
    } catch (err) {
      resultadosProcessados.push({ messageId: msg.id, status: "ERROR", error: err.message });
    }
  }

  return { success: true, totalNaoLidos: messages.length, processados: processed, detalhes: resultadosProcessados };
}

function deveIgnorarAutoresponder(rawFrom, cleanFrom, subject, bodyText) {
  const texto = `${rawFrom} ${cleanFrom} ${subject} ${bodyText}`.toLowerCase();
  const dominiosEEntidades = [
    "edp", "endesa", "iberdrola", "galp", "goldenergy", "luzboa", "plenitude", "e-redes",
    "meo.pt", "telecom.pt", "nos.pt", "vodafone.pt", "nowo.pt", "digi.pt", "altice",
    "otis", "schindler", "thyssen", "thyssenkrupp", "tkelevator", "kone", "liftech", "orona", "eninter",
    "epal", "smas", "indaqua", "aguasdeportugal", "adp.pt",
    "millenniumbcp.pt", "cgd.pt", "caixageral", "santander.pt", "novobanco.pt", "bpi.pt", "bancobpi",
    "bancoctt.pt", "activobank.pt", "bankinter.pt", "montepio.pt", "caixaagricola.pt", "sibs.pt", "unicre.pt",
    "no-reply", "noreply", "nao-responder", "naoresponda", "donotreply", "notifications@", "mailer-daemon"
  ];
  return dominiosEEntidades.some(termo => texto.includes(termo));
}

function getHeader(headers, name) {
  const h = headers.find(h => h.name.toLowerCase() === name.toLowerCase());
  return h?.value || "";
}

function extrairEmailLimpo(str) {
  if (!str) return "";
  const match = str.match(/<([^>]+)>/);
  return match ? match[1].trim() : str.replace(/["']/g, "").trim();
}

function extrairNomeRemetente(rawFrom, cleanFrom) {
  if (!rawFrom) return cleanFrom || "Estimado(a) Condómino(a)";
  const match = rawFrom.match(/^"?([^"<]+)"?\s*<.*>$/);
  if (match && match[1].trim()) return match[1].trim();
  if (cleanFrom && cleanFrom.includes("@")) {
    return cleanFrom.split("@")[0].replace(/[._]/g, " ").replace(/\b\w/g, l => l.toUpperCase());
  }
  return cleanFrom || "Estimado(a) Condómino(a)";
}

function extractBodies(payload) {
  let bodyText = "";
  let bodyHtml = "";
  if (!payload) return { bodyText, bodyHtml };
  const walkParts = (parts) => {
    if (!parts) return;
    for (const p of parts) {
      if (p.mimeType === "text/plain" && p.body?.data) bodyText = decodeBase64Url(p.body.data);
      if (p.mimeType === "text/html" && p.body?.data) bodyHtml = decodeBase64Url(p.body.data);
      if (p.parts) walkParts(p.parts);
    }
  };
  if (payload.parts) walkParts(payload.parts);
  else if (payload.body?.data) bodyText = decodeBase64Url(payload.body.data);
  return { bodyText, bodyHtml };
}

async function extractAttachments(emailData, accessToken) {
  const documentos = [];
  const payload = emailData.payload;
  if (!payload) return documentos;
  const walkParts = (parts) => {
    if (!parts) return;
    for (const part of parts) {
      if (part.filename && part.body && part.body.attachmentId) {
        documentos.push({ _attachmentId: part.body.attachmentId, nome: part.filename, mimeType: part.mimeType || "application/pdf" });
      }
      if (part.parts) walkParts(part.parts);
    }
  };
  walkParts(payload.parts);
  const result = [];
  for (const doc of documentos) {
    try {
      const attachRes = await fetch(
        `https://gmail.googleapis.com/gmail/v1/users/me/messages/${emailData.id}/attachments/${doc._attachmentId}`,
        { headers: { Authorization: `Bearer ${accessToken}` } }
      );
      const attachData = await attachRes.json();
      const base64Clean = (attachData.data || "").replace(/-/g, "+").replace(/_/g, "/");
      result.push({ nome: doc.nome, mimeType: doc.mimeType, base64: base64Clean });
    } catch (e) {
      console.error("Erro anexo:", e);
    }
  }
  return result;
}

function decodeBase64Url(str) {
  try {
    const base64 = str.replace(/-/g, "+").replace(/_/g, "/");
    return decodeURIComponent(atob(base64).split("").map(c => "%" + ("00" + c.charCodeAt(0).toString(16)).slice(-2)).join(""));
  } catch {
    return atob(str.replace(/-/g, "+").replace(/_/g, "/"));
  }
}

async function getAccessToken(env) {
  const res = await fetch("https://oauth2.googleapis.com/token", {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      client_id: env.GMAIL_CLIENT_ID,
      client_secret: env.GMAIL_CLIENT_SECRET,
      refresh_token: env.GMAIL_REFRESH_TOKEN,
      grant_type: "refresh_token"
    })
  });
  const data = await res.json();
  if (!data.access_token) throw new Error(`Falha token Gmail: ${JSON.stringify(data)}`);
  return data.access_token;
}

async function markAsRead(messageId, accessToken) {
  try {
    await fetch(`https://gmail.googleapis.com/gmail/v1/users/me/messages/${messageId}/modify`, {
      method: "POST",
      headers: { Authorization: `Bearer ${accessToken}`, "Content-Type": "application/json" },
      body: JSON.stringify({ removeLabelIds: ["UNREAD"] })
    });
  } catch (e) {
    console.error("Erro ao marcar como lido:", e);
  }
}

