async function guardarNoSupabase(emailData, aiResult, resendStatus, documentos, env) {
  const supabaseUrl = env.SUPABASE_URL;
  const supabaseKey = env.SUPABASE_SERVICE_ROLE_KEY || env.SUPABASE_KEY;

  if (!supabaseUrl || !supabaseKey) {
    console.warn("SUPABASE_URL ou SUPABASE_KEY não configuradas no Worker.");
    return;
  }

  const headers = {
    "apikey": supabaseKey,
    "Authorization": `Bearer ${supabaseKey}`,
    "Content-Type": "application/json",
    "Prefer": "return=representation"
  };

  try {
    // 1. Inserir email
    const emailPayload = [{
      message_id: emailData.messageId || `msg-${Date.now()}`,
      remetente: emailData.from,
      destinatario: emailData.to,
      assunto: emailData.subject,
      corpo_texto: emailData.bodyText || "",
      data_recebido: emailData.date || new Date().toISOString(),
      estado_processamento: "PROCESSADO"
    }];

    const emailRes = await fetch(`${supabaseUrl}/rest/v1/emails_recebidos`, {
      method: "POST",
      headers,
      body: JSON.stringify(emailPayload)
    });

    const emailInserido = await emailRes.json();
    const emailId = emailInserido?.[0]?.id || emailData.messageId;

    // 2. Inserir resultado IA
    if (aiResult && aiResult.dadosExtraidos) {
      await fetch(`${supabaseUrl}/rest/v1/ia_resultados`, {
        method: "POST",
        headers,
        body: JSON.stringify([{
          email_id: emailId,
          tipo_documento: aiResult.classificacao?.tipo || "COMPROVATIVO",
          confianca: aiResult.classificacao?.confianca || 0.9,
          valor_total: aiResult.dadosExtraidos?.valorTotal || null,
          data_documento: aiResult.dadosExtraidos?.dataDocumento || null,
          fracao: aiResult.dadosExtraidos?.fracaoIdentificada || null,
          nif: aiResult.dadosExtraidos?.nif || null,
          entidade: aiResult.dadosExtraidos?.entidade || null,
          resumo: aiResult.dadosExtraidos?.resumo || "",
          raw_json: aiResult
        }])
      });
    }

    // 3. Inserir anexos
    if (Array.isArray(documentos) && documentos.length > 0) {
      const anexosPayload = documentos.map(doc => ({
        email_id: emailId,
        nome_ficheiro: doc.nome || "anexo.pdf",
        mime_type: doc.mimeType || "application/pdf",
        tamanho_bytes: doc.base64 ? doc.base64.length : 0
      }));

      await fetch(`${supabaseUrl}/rest/v1/emails_anexos`, {
        method: "POST",
        headers,
        body: JSON.stringify(anexosPayload)
      });
    }

    // 4. Inserir log
    await fetch(`${supabaseUrl}/rest/v1/emails_logs`, {
      method: "POST",
      headers,
      body: JSON.stringify([{
        email_id: emailId,
        etapa: "AUTO_RESPONDER",
        status: resendStatus?.sucesso ? "SUCESSO" : "INFO",
        detalhes: JSON.stringify({ resend: resendStatus, ai: aiResult?.classificacao })
      }])
    });

    console.log("Registo guardado no Supabase com sucesso!");
  } catch (err) {
    console.error("Erro ao gravar no Supabase:", err);
  }
}
